import 'dart:math';
import 'package:shared_preferences/shared_preferences.dart';

/// 正解インデックスを均等に回すための「袋方式」ピッカー。
/// 例：長さ4なら [0,1,2,3] をシャッフルして先頭から1つずつ消費。尽きたら再充填。
class BalancedIndexPicker {
  /// [length] は choices の数（通常4）。長さごとに独立した袋を持つ。
  static Future<int> next({int length = 4}) async {
    assert(length > 0);
    final prefs = await SharedPreferences.getInstance();
    final key = 'balanced_idx_bag::$length';
    final rnd = Random();

    List<String> bagStr = prefs.getStringList(key) ?? <String>[];
    List<int> bag = bagStr.map((e) => int.tryParse(e) ?? -1).where((e) => e >= 0).toList();

    final valid = bag.isNotEmpty &&
        bag.every((e) => e >= 0 && e < length) &&
        bag.toSet().length <= length;

    if (!valid || bag.isEmpty) {
      bag = List<int>.generate(length, (i) => i)..shuffle(rnd);
    }

    final picked = bag.removeAt(0);
    await prefs.setStringList(key, bag.map((e) => e.toString()).toList());
    return picked;
  }
}

// lib/services/category_repository.dart

import '../models/category_models.dart';

// 既存のデータ定義をそのまま利用
import '../data/categories.dart';          // domains, majorsOf(), midsOf(), topicsOf()
import '../data/hisshu_categories.dart';   // kHisshuCategory, hisshuMajors(), hisshuMidsOf(), hisshuTopicsOf()

/// 既存の関数群（majorsOf/midsOf/topicsOf 等）を“型付きツリー”に変換するリポジトリ。
/// まずは追加だけ。徐々にこちらの型へ置き換えていけます。
class CategoryRepository {
  /// 一般/状況設定の分野ツリーを構築（ドメイン名で指定）
  static DomainCategory buildGeneralDomainTree(String domain) {
    final majorNames = majorsOf(domain);
    final majors = majorNames.map((maj) {
      final midNames = midsOf(domain, maj);
      final mids = midNames.map((mid) {
        final topicNames = topicsOf(domain, maj, mid);
        final topics = topicNames
            .map((t) => Topic(id: t, label: t))
            .toList(growable: false);
        return MidCategory(id: mid, label: mid, topics: topics);
      }).toList(growable: false);
      return MajorCategory(id: maj, label: maj, mids: mids);
    }).toList(growable: false);

    return DomainCategory(id: domain, label: domain, majors: majors);
  }

  /// 必修ツリーを構築（ドメインは kHisshuCategory 固定）
  static DomainCategory buildHisshuTree() {
    final majorNames = hisshuMajors();
    final majors = majorNames.map((maj) {
      final midNames = hisshuMidsOf(maj);
      final mids = midNames.map((mid) {
        final topicNames = hisshuTopicsOf(maj, mid);
        final topics = topicNames
            .map((t) => Topic(id: t, label: t))
            .toList(growable: false);
        return MidCategory(id: mid, label: mid, topics: topics);
      }).toList(growable: false);
      return MajorCategory(id: maj, label: maj, mids: mids);
    }).toList(growable: false);

    return DomainCategory(id: kHisshuCategory, label: kHisshuCategory, majors: majors);
  }

  // ========== 以下は“移行を楽にする”ための薄いFacade（今のAPIを保ったまま裏で型へ） ==========

  static List<String> generalDomains() => domains;

  static List<String> generalMajorsOf(String domain) => majorsOf(domain);

  static List<String> generalMidsOf(String domain, String major) =>
      midsOf(domain, major);

  static List<String> generalTopicsOf(String domain, String major, String mid) =>
      topicsOf(domain, major, mid);

  static List<String> hisshuMajorItems() => hisshuMajors();

  static List<String> hisshuMids(String major) => hisshuMidsOf(major);

  static List<String> hisshuTopics(String major, String mid) =>
      hisshuTopicsOf(major, mid);
}

// lib/services/choice_normalizer.dart
//
// モデルが返す JSON から choices と正答を正規化するユーティリティ。
// QuestionService 以外からも再利用できるよう公開クラスで提供。


class ChoiceItem {
  final String text;
  final bool isCorrect;
  final String? rationale;
  ChoiceItem({required this.text, required this.isCorrect, this.rationale});
}

class NormalizedChoices {
  final List<ChoiceItem> items;
  NormalizedChoices(this.items);
}

class ChoiceNormalizer {
  /// JSON から choices と正答を正規化（内部形式：リスト＋ isCorrect＋ rationale）
  static NormalizedChoices normalize(Map<String, dynamic> json) {
    final dynamic rawChoices = json['choices'];

    // rationales は A-D マップ or 配列 or インデックス・マップかもしれないので柔軟に扱う
    final dynamic rawRationales =
        json['rationales'] ?? json['reasons'] ?? json['rationale'];

    // 正答マーカー抽出
    final int? idxFromNum =
    _asInt(json['correctIndex'] ?? json['answer_index'] ?? json['answerIndex']);
    final String letterFromJson =
    (json['correct'] ?? json['correctLetter'] ?? json['answer_key'] ?? json['answer'] ?? '')
        .toString()
        .trim();

    if (rawChoices is List) {
      // 例：["a","b","c","d"]
      final list =
      rawChoices.map((e) => (e ?? '').toString()).where((s) => s.isNotEmpty).toList();
      // 2〜4 要素に丸める（多すぎる分は切り捨て）
      final limited = list.length > 4 ? list.take(4).toList() : list;

      // インデックスの確定
      int correctIdx = 0;
      if (idxFromNum != null && idxFromNum >= 0 && idxFromNum < limited.length) {
        correctIdx = idxFromNum;
      } else {
        final idxFromLetter = _letterToIndex(letterFromJson);
        if (idxFromLetter != null && idxFromLetter >= 0 && idxFromLetter < limited.length) {
          correctIdx = idxFromLetter;
        } else {
          // モデルが返さない場合は 0 を正答として受け取り、あとでシャッフルで位置を均等化
          correctIdx = 0;
        }
      }

      // ラショナーレの取り出し（配列 or A-D or インデックス）
      final rationalsByIndex = _extractRationalesByIndex(rawRationales, limited.length);

      final items = <ChoiceItem>[];
      for (var i = 0; i < limited.length; i++) {
        items.add(ChoiceItem(
          text: limited[i],
          isCorrect: i == correctIdx,
          rationale: rationalsByIndex[i],
        ));
      }
      return NormalizedChoices(items);
    }

    if (rawChoices is Map) {
      // 例：{"A":"a","B":"b","C":"c","D":"d"}
      final order = ['A', 'B', 'C', 'D', 'E', 'F'];
      final entries = <MapEntry<String, String>>[];
      for (final k in order) {
        final v = rawChoices[k];
        if (v == null) continue;
        final s = v.toString();
        if (s.trim().isEmpty) continue;
        entries.add(MapEntry(k, s));
      }
      // 2〜4件に制限
      final limited = entries.take(4).toList();

      // 正答：数値 or 文字
      int correctIdx = 0;
      if (idxFromNum != null && idxFromNum >= 0 && idxFromNum < limited.length) {
        correctIdx = idxFromNum;
      } else {
        final idxFromLetter = _letterToIndex(letterFromJson);
        if (idxFromLetter != null && idxFromLetter >= 0 && idxFromLetter < limited.length) {
          correctIdx = idxFromLetter;
        } else {
          correctIdx = 0;
        }
      }

      // ラショナーレ取得（A-D マップ基準で受け取り → インデックスへ）
      final rationalsByIndex =
      _extractRationalesByIndexFromLetterMap(rawRationales, limited.length);

      final items = <ChoiceItem>[];
      for (var i = 0; i < limited.length; i++) {
        items.add(ChoiceItem(
          text: limited[i].value,
          isCorrect: i == correctIdx,
          rationale: rationalsByIndex[i],
        ));
      }
      return NormalizedChoices(items);
    }

    // choices が不正な場合のフォールバック
    final fallback = [
      ChoiceItem(text: '選択肢 1', isCorrect: true),
      ChoiceItem(text: '選択肢 2', isCorrect: false),
      ChoiceItem(text: '選択肢 3', isCorrect: false),
      ChoiceItem(text: '選択肢 4', isCorrect: false),
    ];
    return NormalizedChoices(fallback);
  }

  static int? _asInt(dynamic v) {
    if (v == null) return null;
    if (v is int) return v;
    if (v is num) return v.toInt();
    if (v is String) return int.tryParse(v);
    return null;
  }

  static int? _letterToIndex(String s) {
    if (s.isEmpty) return null;
    final up = s.trim().toUpperCase();
    final code = up.codeUnitAt(0) - 'A'.codeUnitAt(0);
    if (code < 0 || code > 25) return null;
    return code;
  }

  /// rationales をインデックス基準の Map<int,String> に変換（choices が配列のとき）
  static Map<int, String> _extractRationalesByIndex(dynamic raw, int length) {
    if (raw == null) return {};
    // 配列とみなせる場合
    if (raw is List) {
      final out = <int, String>{};
      for (var i = 0; i < raw.length && i < length; i++) {
        final s = raw[i]?.toString() ?? '';
        if (s.trim().isNotEmpty) out[i] = s;
      }
      return out;
    }
    // 文字キー（A〜D）のマップ
    if (raw is Map) {
      final byLetter = _extractRationalesByIndexFromLetterMap(raw, length);
      return byLetter;
    }
    return {};
  }

  /// rationales が A〜D キーのマップだった場合に、インデックス基準に変換
  static Map<int, String> _extractRationalesByIndexFromLetterMap(dynamic raw, int length) {
    if (raw is! Map) return {};
    final out = <int, String>{};
    const letters = ['A', 'B', 'C', 'D', 'E', 'F'];
    for (var i = 0; i < length && i < letters.length; i++) {
      final s = raw[letters[i]]?.toString() ?? '';
      if (s.trim().isNotEmpty) out[i] = s;
    }
    return out;
  }
}

// lib/services/exam_score_service.dart
import '../models/answer_history.dart';

/// 国試の大きな区分
/// - 必修
/// - 一般
/// - 状況設定
enum ExamSection {
  hisshu,
  ippan,
  jokyo,
}

/// 国試スコアの集計結果
class ExamScore {
  final int answeredHisshu;
  final int correctHisshu;

  /// 一般 + 状況設定 をまとめた数
  final int answeredGeneralLike;
  final int correctGeneralLike;

  /// 必修正答率 (0.0〜1.0)
  final double hisshuRate;

  /// 一般＋状況設定 正答率 (0.0〜1.0)
  final double generalRate;

  /// 必修スコア（0〜50点にスケーリング）
  final double hisshuScore;

  /// 一般+状況設定スコア（0〜350点にスケーリング）
  final double generalScore;

  /// 合計スコア（0〜400点）
  double get totalScore => hisshuScore + generalScore;

  /// 必修合格ライン（8割以上）
  final bool isPassHisshu;

  /// 一般+状況 合格ライン（6割以上想定）
  final bool isPassGeneral;

  /// 両方クリアしているか
  bool get isPass => isPassHisshu && isPassGeneral;

  /// データが「そこそこ十分にある」と言えるかの目安
  final bool hasEnoughData;

  const ExamScore({
    required this.answeredHisshu,
    required this.correctHisshu,
    required this.answeredGeneralLike,
    required this.correctGeneralLike,
    required this.hisshuRate,
    required this.generalRate,
    required this.hisshuScore,
    required this.generalScore,
    required this.isPassHisshu,
    required this.isPassGeneral,
    required this.hasEnoughData,
  });
}

/// 国試スコア計算サービス
class ExamScoreService {
  ExamScoreService._();

  /// AnswerRecord から difficulty を見て区分を推定
  static ExamSection? sectionOfRecord(AnswerRecord r) {
    final d = (r.difficulty).trim();

    // ここは今後、実際の difficulty のラベルに合わせて追加していけばOK
    if (d.contains('必修')) {
      return ExamSection.hisshu;
    }
    if (d.contains('状況')) {
      return ExamSection.jokyo;
    }
    if (d.contains('一般')) {
      return ExamSection.ippan;
    }

    // どれにも当てはまらなければ null（集計対象外）
    return null;
  }

  /// 解答履歴一覧から国試スコアを集計
  ///
  /// スコアの考え方:
  /// - 必修：正答率 × 50点
  /// - 一般+状況：正答率 × 350点
  /// （＝「もし今の正答率のまま本番を全問解いたら何点か」のイメージ）
  static ExamScore calculate(List<AnswerRecord> records) {
    int answeredHisshu = 0;
    int correctHisshu = 0;

    int answeredGeneralLike = 0; // 一般 + 状況設定
    int correctGeneralLike = 0;

    for (final r in records) {
      final sec = sectionOfRecord(r);
      if (sec == null) continue;

      switch (sec) {
        case ExamSection.hisshu:
          answeredHisshu++;
          if (r.isCorrect) correctHisshu++;
          break;
        case ExamSection.ippan:
        case ExamSection.jokyo:
          answeredGeneralLike++;
          if (r.isCorrect) correctGeneralLike++;
          break;
      }
    }

    double _rate(int correct, int total) {
      if (total == 0) return 0.0;
      return correct / total;
    }

    final hisshuRate = _rate(correctHisshu, answeredHisshu);
    final generalRate = _rate(correctGeneralLike, answeredGeneralLike);

    // ★ スコア換算
    final hisshuScore = hisshuRate * 50.0;
    final generalScore = generalRate * 350.0;

    // ★ 合否判定（目安）
    final isPassHisshu = hisshuRate >= 0.8; // 8割以上
    final isPassGeneral = generalRate >= 0.6; // 6割以上想定

    // ★ データ量の目安（あくまで参考）
    final hasEnoughData =
        answeredHisshu >= 10 && answeredGeneralLike >= 30;

    return ExamScore(
      answeredHisshu: answeredHisshu,
      correctHisshu: correctHisshu,
      answeredGeneralLike: answeredGeneralLike,
      correctGeneralLike: correctGeneralLike,
      hisshuRate: hisshuRate,
      generalRate: generalRate,
      hisshuScore: hisshuScore,
      generalScore: generalScore,
      isPassHisshu: isPassHisshu,
      isPassGeneral: isPassGeneral,
      hasEnoughData: hasEnoughData,
    );
  }
}

// lib/services/history_stats.dart
import 'package:collection/collection.dart';
import '../models/history_models.dart';

/// 履歴（HistoryRecordのリスト）から、グラフに必要な統計値を計算する純ロジック。
/// UIやストレージから独立しているため、テストもしやすい構成です。
class HistoryStats {
  /// 日別要約（accuracyは DailySummary.accuracy で参照）
  static List<DailySummary> dailySummaries(List<HistoryRecord> all) {
    if (all.isEmpty) return const [];

    // 日付キー（ローカル日付の 00:00）でグルーピング
    final groups = groupBy<HistoryRecord, DateTime>(
      all,
          (r) => DateTime(r.timestamp.year, r.timestamp.month, r.timestamp.day),
    );

    final out = <DailySummary>[];
    for (final entry in groups.entries) {
      final date = entry.key;
      final records = entry.value;
      final total = records.length;
      final correct = records.where((r) => r.correct).length;
      out.add(DailySummary(date: date, total: total, correct: correct));
    }

    out.sort((a, b) => a.date.compareTo(b.date));
    return out;
  }

  /// ドメイン別要約（accuracyは DomainSummary.accuracy で参照）
  static List<DomainSummary> domainSummaries(List<HistoryRecord> all) {
    if (all.isEmpty) return const [];

    final groups = groupBy<HistoryRecord, String>(all, (r) => r.domain);
    final out = <DomainSummary>[];

    for (final entry in groups.entries) {
      final domain = entry.key;
      final records = entry.value;
      final total = records.length;
      final correct = records.where((r) => r.correct).length;
      out.add(DomainSummary(domain: domain, total: total, correct: correct));
    }

    out.sort((a, b) => a.domain.compareTo(b.domain));
    return out;
  }

  /// 移動平均精度（windowDays 日のローリング）
  /// 例：windowDays=7 → 各日について直近7日間の正答率を算出
  static List<RollingPoint> rollingAccuracyByDay(
      List<HistoryRecord> all, {
        int windowDays = 7,
      }) {
    final daily = dailySummaries(all);
    if (daily.isEmpty) return const [];

    final out = <RollingPoint>[];

    for (var i = 0; i < daily.length; i++) {
      final end = daily[i].date;
      final start = end.subtract(Duration(days: windowDays - 1));
      int total = 0;
      int correct = 0;

      for (var j = 0; j <= i; j++) {
        final d = daily[j];
        if (d.date.isBefore(start) || d.date.isAfter(end)) continue;
        total += d.total;
        correct += d.correct;
      }

      final acc = total == 0 ? 0.0 : correct / total;
      out.add(RollingPoint(date: end, accuracy: acc));
    }
    return out;
  }

  /// 直近N問の正答率（質問数ベースの移動窓）
  static double recentAccuracy(List<HistoryRecord> all, {int lastN = 20}) {
    if (all.isEmpty) return 0.0;
    final slice = (all.length <= lastN) ? all : all.sublist(all.length - lastN);
    final total = slice.length;
    final correct = slice.where((r) => r.correct).length;
    return total == 0 ? 0.0 : correct / total;
  }

  /// 正解・不正解の連続記録
  static Streaks streaks(List<HistoryRecord> all) {
    int currentCorrect = 0, bestCorrect = 0;
    int currentWrong = 0, bestWrong = 0;

    for (final r in all) {
      if (r.correct) {
        currentCorrect += 1;
        bestCorrect = currentCorrect > bestCorrect ? currentCorrect : bestCorrect;
        currentWrong = 0;
      } else {
        currentWrong += 1;
        bestWrong = currentWrong > bestWrong ? currentWrong : bestWrong;
        currentCorrect = 0;
      }
    }

    return Streaks(
      currentCorrect: currentCorrect,
      bestCorrect: bestCorrect,
      currentWrong: currentWrong,
      bestWrong: bestWrong,
    );
  }

  /// 指定ドメイン/大項目でフィルタ。UI側のドロップダウンと組み合わせやすい。
  static List<HistoryRecord> filter({
    required List<HistoryRecord> all,
    String? domain,
    String? major,
    String? mid,
  }) {
    return all.where((r) {
      if (domain != null && domain.isNotEmpty && r.domain != domain) return false;
      if (major != null && major.isNotEmpty && r.major != major) return false;
      if (mid != null && mid.isNotEmpty && r.mid != mid) return false;
      return true;
    }).toList();
  }
}

// lib/services/notice_prefs.dart
import 'package:shared_preferences/shared_preferences.dart';

class NoticePrefs {
  static const _keyReadIds = 'notice_read_ids';

  /// 既読ID一覧を取得
  static Future<Set<String>> getReadIds() async {
    final prefs = await SharedPreferences.getInstance();
    final list = prefs.getStringList(_keyReadIds) ?? <String>[];
    return list.toSet();
  }

  /// 指定した noticeId を既読に追加
  static Future<void> markAsRead(String noticeId) async {
    final prefs = await SharedPreferences.getInstance();
    final list = prefs.getStringList(_keyReadIds) ?? <String>[];

    if (!list.contains(noticeId)) {
      list.add(noticeId);
      await prefs.setStringList(_keyReadIds, list);
    }
  }

  /// 全既読クリア（テスト用）
  static Future<void> clearReads() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(_keyReadIds);
  }
}

// lib/services/notice_service.dart
import 'dart:convert';
import 'package:flutter/services.dart' show rootBundle;

import '../models/notice.dart';
import 'notice_prefs.dart';

class NoticeService {
  static const String _assetPath = 'assets/notices.json';
  static List<Notice>? _cache;

  /// 全お知らせ（新→古）
  static Future<List<Notice>> all() async {
    if (_cache != null) return _cache!;
    final jsonStr = await rootBundle.loadString(_assetPath);

    final list = json.decode(jsonStr) as List;
    final notices = list.map((e) {
      try {
        return Notice.fromJson(e);
      } catch (_) {
        return null;
      }
    }).whereType<Notice>().toList();

    notices.sort((a, b) => b.publishedAt.compareTo(a.publishedAt));
    _cache = notices;
    return notices;
  }

  /// 最新のお知らせ
  static Future<Notice?> latest() async {
    final allItems = await all();
    if (allItems.isEmpty) return null;
    return allItems.first;
  }

  /// 未読件数を返す（readIds で判定）
  static Future<int> unreadCount() async {
    final notices = await all();
    final readIds = await NoticePrefs.getReadIds();
    return notices.where((n) => !readIds.contains(n.id)).length;
  }
}

// lib/services/past_exam_catalog.dart
import 'dart:convert';
import 'package:flutter/services.dart' show rootBundle;

class PastExamCatalog {
  PastExamCatalog._();
  static final PastExamCatalog instance = PastExamCatalog._();

  List<PastExamMeta> _exams = const [];
  bool _loaded = false;

  List<PastExamMeta> get exams => _exams;

  Future<void> ensureLoaded() async {
    if (_loaded) return;
    _loaded = true;

    final raw = await rootBundle.loadString('assets/past_exam/catalog.json');
    final decoded = jsonDecode(raw) as Map<String, dynamic>;
    final list = (decoded['exams'] as List<dynamic>? ?? const [])
        .whereType<Map>()
        .map((e) => PastExamMeta.fromJson(Map<String, dynamic>.from(e)))
        .toList();

    _exams = list;
  }

  PastExamMeta? findById(String id) {
    for (final e in _exams) {
      if (e.id == id) return e;
    }
    return null;
  }
}

class PastExamMeta {
  final String id;
  final String title;
  final List<PastExamPartMeta> parts;

  const PastExamMeta({
    required this.id,
    required this.title,
    required this.parts,
  });

  factory PastExamMeta.fromJson(Map<String, dynamic> j) {
    return PastExamMeta(
      id: (j['id'] ?? '').toString(),
      title: (j['title'] ?? '').toString(),
      parts: ((j['parts'] as List<dynamic>? ?? const []))
          .whereType<Map>()
          .map((p) => PastExamPartMeta.fromJson(Map<String, dynamic>.from(p)))
          .toList(),
    );
  }
}

class PastExamPartMeta {
  final String key;         // assets/past_exam/<examId>/<key>.json
  final String label;       // 画面表示
  final String description; // 画面表示
  final String kind;        // 必修/一般/状況設定（フィルタ用）

  const PastExamPartMeta({
    required this.key,
    required this.label,
    required this.description,
    required this.kind,
  });

  factory PastExamPartMeta.fromJson(Map<String, dynamic> j) {
    return PastExamPartMeta(
      key: (j['key'] ?? '').toString(),
      label: (j['label'] ?? '').toString(),
      description: (j['description'] ?? '').toString(),
      kind: (j['kind'] ?? '').toString(),
    );
  }
}

// lib/services/past_exam_repository.dart
import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

import '../models/nurai_question.dart';

/// 画面用：パート表示メタ
class PastExamPartMeta {
  final String label;       // 例: 必修問題 午前
  final String description; // 例: 必修 午前の問題を解く
  final String partKey;     // 例: hisshu_am
  final bool enabled;

  const PastExamPartMeta({
    required this.label,
    required this.description,
    required this.partKey,
    this.enabled = true,
  });
}

class PastExamRepository {
  PastExamRepository._();
  static final PastExamRepository instance = PastExamRepository._();

  // ---- キャッシュ ----
  Map<String, dynamic>? _assetManifest;
  final Map<String, List<PastExamPartMeta>> _partsCache = {};
  final Map<String, int> _totalCache = {};

  Future<Map<String, dynamic>> _loadManifest() async {
    if (_assetManifest != null) return _assetManifest!;
    final raw = await rootBundle.loadString('AssetManifest.json');
    final decoded = jsonDecode(raw);
    final map = Map<String, dynamic>.from(decoded as Map);
    _assetManifest = map;
    return map;
  }

  /// assets/past_exam/<examId>/ 配下の json を列挙して partKey を作る
  Future<List<PastExamPartMeta>> partsForExam(String examId) async {
    if (_partsCache.containsKey(examId)) return _partsCache[examId]!;

    final manifest = await _loadManifest();
    final prefix = 'assets/past_exam/$examId/';
    final keys = manifest.keys
        .where((k) => k.startsWith(prefix) && k.toLowerCase().endsWith('.json'))
        .toList()
      ..sort();

    if (keys.isEmpty) {
      _partsCache[examId] = const [];
      return const [];
    }

    final parts = <PastExamPartMeta>[];
    for (final path in keys) {
      final file = path.split('/').last; // hisshu_am.json
      final partKey = file.replaceAll('.json', '');

      final label = _labelFromPartKey(partKey);
      final desc = _descFromPartKey(partKey);

      parts.add(
        PastExamPartMeta(
          label: label.isEmpty ? partKey : label,
          description: desc.isEmpty ? 'このパートの問題を解く' : desc,
          partKey: partKey,
          enabled: true,
        ),
      );
    }

    _partsCache[examId] = parts;
    return parts;
  }

  /// 1パート読み込み（固定API名：load）
  Future<List<NuraiQuestion>> load({
    required String examId,
    required String partKey,
  }) async {
    final assetPath = 'assets/past_exam/$examId/$partKey.json';
    final raw = await rootBundle.loadString(assetPath);

    dynamic decoded;
    try {
      decoded = jsonDecode(raw);
    } catch (_) {
      // JSONが壊れている場合は空扱い
      return const [];
    }

    if (decoded is! List) return const [];

    final out = <NuraiQuestion>[];
    for (var i = 0; i < decoded.length; i++) {
      final item = decoded[i];
      if (item is! Map) continue;

      final j = Map<String, dynamic>.from(item as Map);

      // ---- 背景文（任意） ----
      final backgroundText = (j['backgroundText'] ??
          j['background'] ??
          j['context'] ??
          j['scenario'] ??
          j['scenarioText'])
          ?.toString();

      final questionText = (j['question'] ?? j['questionText'] ?? '').toString();

      // ---- choices ----
      final choicesRaw = j['choices'];
      final choices = <String, String>{};
      if (choicesRaw is Map) {
        final m = Map<String, dynamic>.from(choicesRaw as Map);
        for (final e in m.entries) {
          choices[e.key.toString()] = (e.value ?? '').toString();
        }
      }

      // ---- correctLabels ----
      final ca = j['correctAnswers'] ?? j['correctLabels'] ?? j['answer'];
      final correctLabels = <String>[];
      if (ca is List) {
        correctLabels.addAll(
          ca.map((e) => (e ?? '').toString()).where((s) => s.trim().isNotEmpty),
        );
      } else if (ca != null) {
        final s = ca.toString().trim();
        if (s.isNotEmpty) correctLabels.add(s);
      }

      // ---- choiceRationales（過去問JSONのキー） ----
      final rk = j['choiceRationales'];
      Map<String, String>? choiceRationales;
      if (rk is Map) {
        final m = Map<String, dynamic>.from(rk as Map);
        choiceRationales = m.map((k, v) => MapEntry(k.toString(), (v ?? '').toString()));
      }

      final explanation = j['explanation']?.toString();

      final questionKind = (j['questionKind'] ?? j['kind'] ?? 'single').toString();
      final requiredCorrectCount = (j['requiredCorrectCount'] is int)
          ? (j['requiredCorrectCount'] as int)
          : (correctLabels.isNotEmpty ? correctLabels.length : 1);

      final sourceType = (j['sourceType'] ?? 'past_exam').toString();

      // sourceTag：無ければ自動生成（キー安定用）
      final rawTag = (j['sourceTag'] ?? j['tag'])?.toString().trim() ?? '';
      final sourceTag = rawTag.isNotEmpty
          ? rawTag
          : _defaultSourceTag(examId: examId, partKey: partKey, index1: i + 1);

      // 画像：figure / imagePath を許容
      final imagePath = (j['imagePath'] ?? j['figure'])?.toString();
      final imageRequired = (j['imageRequired'] == true);

      out.add(
        NuraiQuestion(
          questionText: questionText,
          backgroundText: (backgroundText ?? '').trim().isEmpty ? null : backgroundText,
          choices: choices,
          correctLabels: correctLabels,
          choiceRationales: choiceRationales,
          explanation: explanation,
          questionKind: questionKind,
          requiredCorrectCount: requiredCorrectCount,
          difficulty: (j['difficulty'] ?? '').toString(),
          domain: (j['domain'] ?? '').toString(),
          major: (j['major'] ?? '').toString(),
          mid: j['mid']?.toString(),
          topic: j['topic']?.toString(),
          sourceType: sourceType,
          sourceTag: sourceTag,
          imagePath: imagePath,
          imageRequired: imageRequired,
        ),
      );
    }

    return out;
  }

  /// 総問題数（全パート合算）
  Future<int> totalQuestionsOfExam(String examId) async {
    if (_totalCache.containsKey(examId)) return _totalCache[examId]!;

    final parts = await partsForExam(examId);
    if (parts.isEmpty) {
      _totalCache[examId] = 0;
      return 0;
    }

    var total = 0;
    for (final p in parts) {
      try {
        final list = await load(examId: examId, partKey: p.partKey);
        total += list.length;
      } catch (_) {
        // 読めないパートは 0 として続行（クラッシュ防止）
      }
    }

    _totalCache[examId] = total;
    return total;
  }

  void clearCache() {
    _assetManifest = null;
    _partsCache.clear();
    _totalCache.clear();
  }

  // ====== 表示名生成 ======

  String _labelFromPartKey(String partKey) {
    final lower = partKey.toLowerCase();

    String kind = '';
    if (lower.startsWith('hisshu')) kind = '必修問題';
    if (lower.startsWith('ippan')) kind = '一般問題';
    if (lower.startsWith('situation') || lower.startsWith('jokyo')) kind = '状況設定問題';

    String time = '';
    if (lower.endsWith('_am')) time = '午前';
    if (lower.endsWith('_pm')) time = '午後';

    if (kind.isEmpty && time.isEmpty) return '';
    return [kind, time].where((s) => s.isNotEmpty).join(' ');
  }

  String _descFromPartKey(String partKey) {
    final label = _labelFromPartKey(partKey);
    if (label.isEmpty) return '';
    final t = label.replaceAll('問題', '');
    return '$t の問題を解く';
  }

  String _defaultSourceTag({
    required String examId,
    required String partKey,
    required int index1,
  }) {
    return 'past_exam:$examId:$partKey:$index1';
  }
}

// lib/services/prompt_builder.dart

/// OpenAI へ送るプロンプト（system / user）の組み立てを担当するユーティリティ。
class PromptBuilder {
  /// system プロンプト（固定方針＋ハード制約）
  ///
  /// - 必ず JSON オブジェクトのみを返す（前後に説明文やコードフェンスを付けない）
  /// - `questionKind` は desiredKind と一致させる
  /// - 選択肢数は desiredChoiceCount 個「ちょうど」
  /// - 正答数は requiredCorrectCount と一致（single=1 / multiple=2）
  /// - "select_incorrect" のときは、`correctAnswers` に「誤っている選択肢」のラベルを入れる
  /// - 医学・看護学的に整合した正誤になるよう、自己チェックを行う
  ///
  /// 出力スキーマ:
  ///   {
  ///     "question": string,
  ///     "choices": { "A": string, "B": string, ... },   // A..D または A..E
  ///     "correctAnswers": [ "A", ... ],                  // ラベル配列（1 or 2）
  ///     "questionKind": "single" | "multiple" | "select_incorrect",
  ///     "explanation": string,
  ///     "rationales": { "A": string, "B": string, ... } // 任意
  ///   }
  static String buildSystemPrompt({
    String desiredKind = 'single',
    int desiredChoiceCount = 4,
    int requiredCorrectCount = 1,
  }) {
    return [
      'あなたは日本の看護師国家試験の出題委員です。',
      '厚労省の出題基準に準拠し、日本語として自然で学術的に正確な択一式問題を作成します。',
      '出力は必ず JSON オブジェクトのみ（前後に余計な文字やコードフェンスを含めない）。',

      '',
      '【厳守すべき形式制約】',
      '- "questionKind" は必ず "$desiredKind" とする。',
      '- 選択肢 "choices" は { "A": "...", "B": "...", ... } の連想配列形式で、キーは A から始まる昇順 (A〜${desiredChoiceCount == 5 ? 'E' : 'D'})。',
      '- 選択肢の個数は ちょうど $desiredChoiceCount 個にする（多すぎ/少なすぎは禁止）。',
      '- "correctAnswers" は ["A", ...] の形で、要素数は $requiredCorrectCount 個に一致させる。',
      '- single のときは正答は 1 個、multiple のときは正答は 2 個に固定。',
      '- "select_incorrect" のときは、"correctAnswers" には「誤っている選択肢」のラベルだけを入れる（正しい選択肢のラベルは絶対に含めない）。',

      '',
      '【内容上の厳格な条件】',
      '- 医学・看護学的に明確な正誤が判断できるテーマを扱う。',
      '- 正しい選択肢は、解説や rationales でも「正しい」「妥当」など一貫して肯定される内容にする。',
      '- 誤っている選択肢は、解説や rationales でも「誤り」「不適切」など一貫して否定される内容にする。',
      '- "select_incorrect" のとき:',
      '  - 選択肢のうち $requiredCorrectCount 個だけ明確に誤った記述にし、それ以外は明確に正しい記述にする。',
      '  - "correctAnswers" には、その誤った選択肢のラベルだけを列挙する。',
      '- "multiple" のとき:',
      '  - 正答の選択肢同士は、すべて正しい内容で互いに矛盾しないようにする。',
      '  - 誤答の選択肢は、明確な誤りを含む記述にする。',
      '- "single" のとき:',
      '  - 正答は 1 つだけが明らかに正しく、他は明らかに誤りになるようにする。',

      '',
      '【自己チェック】',
      '- 出力する前に、次のチェックを必ず行うこと:',
      '  1) "correctAnswers" に含まれるラベルの選択肢が、本当に指定の意味で正しい／誤っているか（問題文の指示と矛盾しないか）。',
      '  2) "explanation" と "rationales" が、"correctAnswers" に指定したラベルと論理的に矛盾していないか。',
      '  3) "select_incorrect" の場合、"correctAnswers" の各ラベルの文章が、本当に誤った記述になっているか。',

      '',
      '【禁止事項】',
      '- JSON 以外の文字、注釈、コードフェンス、整形エラー。',
      '- 指定個数と異なる選択肢数や正答数。',
      '- 正しいはずの選択肢を「誤答」として "correctAnswers" に含めること。',
      '- 誤っているはずの選択肢を「正答」として扱うこと。',

      '',
      '【出力スキーマ】',
      '{',
      '  "question": string,',
      '  "choices": { "A": string, "B": string, "C": string, "D": string' +
          (desiredChoiceCount == 5 ? ', "E": string' : '') +
          ' },',
      '  "correctAnswers": [ "A"' + (requiredCorrectCount == 2 ? ', "B"' : '') + ' ],',
      '  "questionKind": "single" | "multiple" | "select_incorrect",',
      '  "explanation": string,',
      '  "rationales": { "A": string, "B": string, "C": string, "D": string' +
          (desiredChoiceCount == 5 ? ', "E": string' : '') +
          ' }',
      '}',
    ].join('\n');
  }

  /// user プロンプト（出題条件）
  static String buildUserPrompt({
    required String difficulty,     // 必修問題 / 一般問題 / 状況設定問題
    required String domain,         // 例：人体の構造と機能
    required String major,          // 例：循環器系
    String? mid,
    String? topic,
    String? scenarioAspect,
    String desiredKind = 'single',  // single / multiple / select_incorrect
    int desiredChoiceCount = 4,     // 4 or 5
    int requiredCorrectCount = 1,   // single=1, multiple=2 など
  }) {
    final b = StringBuffer();
    b.writeln('出題形式: $difficulty');
    b.writeln('分野: $domain');
    b.writeln('大項目: $major');
    if (mid != null && mid.isNotEmpty) b.writeln('中項目: $mid');
    if (topic != null && topic.isNotEmpty) b.writeln('トピック: $topic');
    if (scenarioAspect != null && scenarioAspect.isNotEmpty) {
      b.writeln('状況設定の観点: $scenarioAspect');
    }
    b.writeln('');

    b.writeln('【問題生成の仕様】');
    b.writeln('- questionKind は "$desiredKind" に固定する。');
    b.writeln('- 選択肢は $desiredChoiceCount 個に固定（A..' +
        (desiredChoiceCount == 5 ? 'E' : 'D') + '）。');
    b.writeln('- 正答数は $requiredCorrectCount 個に固定する。');
    if (desiredKind == 'select_incorrect') {
      b.writeln('- select_incorrect の場合、"correctAnswers" は「誤っている選択肢」のラベルだけを列挙する（正しい選択肢は絶対に含めない）。');
      b.writeln('- 誤っている選択肢は、明確に誤りと分かる内容にし、他の選択肢は明確に正しい内容にする。');
    } else {
      b.writeln('- single/multiple の場合、"correctAnswers" は内容的に正しい選択肢のラベルだけを列挙する。');
      b.writeln('- 誤答選択肢には、事実と異なる、もしくは不適切な記述を入れる。');
    }
    b.writeln('- 出力は必ず JSON オブジェクトのみ。');
    b.writeln('- 各選択肢は重複や曖昧さがないように明確に作成する。');
    b.writeln('- 解説は根拠を簡潔に示す。可能なら各選択肢の理由 (rationales) を付与する。');

    b.writeln('');
    b.writeln('【自己チェック】');
    b.writeln('- 出力前に、次の点を必ず確認してから JSON を返すこと:');
    b.writeln('  1) 問題文の指示（「正しいものを選べ」「誤っているものを選べ」など）と、"correctAnswers" の意味が一致しているか。');
    b.writeln('  2) "correctAnswers" に含まれるラベルの文章が、解説・rationales の内容と矛盾していないか。');

    // =========================
    // ここから「状況設定問題」専用の追加要件
    // =========================
    if (difficulty == '状況設定問題') {
      b.writeln('');
      b.writeln('【状況設定問題としての追加要件】');
      b.writeln('- 問題文全体は「状況設定文＋設問」という構成にする。');
      b.writeln('- "question" フィールドのテキストは、次の構造を持つ 1 本の文章とする:');
      b.writeln('  1) 冒頭に「次の文を読み問題に答えよ。」などの指示文を置く。');
      b.writeln('  2) その後に、患者や家族などの背景を説明する状況設定文を 3〜6 文程度書く。');
      b.writeln('     - 年齢（例：◯歳の男性／女性）');
      b.writeln('     - 職業や生活背景（例：会社員、一人暮らし、夫と二人暮らし など）');
      b.writeln('     - 既往歴や治療歴、家族構成、生活上の困りごとなど');
      b.writeln('     - 発症のきっかけや現在の症状、受診の経緯 など');
      b.writeln('  3) 最後に「問題1」または「このとき看護師の対応として最も適切なのはどれか。」など、国試の設問らしい一文で締める。');
      b.writeln('- 文章量の目安は全体で日本語 300〜600字程度とし、短すぎず長すぎない分量にする。');
      b.writeln('- 会話文だけにならないようにし、地の文（叙述）と会話をバランスよく用いる。');
      b.writeln('- 時系列の流れ（受診前 → 受診時 → 受診後 など）がある程度わかるように記述する。');
      b.writeln('- 看護師が判断・対応を問われる文脈（観察、情報収集、家族への支援、多職種連携など）を明確に示す。');
      b.writeln('- 実際の看護師国家試験の状況設定問題の雰囲気に近づける。');
      b.writeln('- 設問の主語は「看護師」や「看護管理者」などを用い、国家試験らしい問い方にする。');
    }

    return b.toString();
  }
}

